con:configuration.scriptText:
def MIN_VERSION = "1.1"

def requestContent = messageExchange.request
def m = requestContent =~ /(?s)<tem:aanvraagxmldata>(.*?)<\/tem:aanvraagxmldata>/
if (!m) {
    log.warn("Geen tem:aanvraagxmldata gevonden in dit verzoek - versiecheck overgeslagen")
    return
}
def b64 = m[0][1].replaceAll(/\s+/, "")
def decoded = new String(b64.decodeBase64(), "UTF-8")

def vm = decoded =~ /WebformulierenVerwerker_Passthrough\.xml, versie ([0-9]+)\.([0-9]+)/
if (!vm) {
    assert false : "Geen versie-commentaar van WebformulierenVerwerker_Passthrough.xml gevonden in de aangeleverde aanvraagxmldata - oude (kale) Atabix-stylesheet of nog het oude formulierformaat gebruikt?"
}

def major = vm[0][1].toInteger()
def minor = vm[0][2].toInteger()
def minParts = MIN_VERSION.split("\.")
def minMajor = minParts[0].toInteger()
def minMinor = minParts[1].toInteger()

def ok = (major > minMajor) || (major == minMajor && minor >= minMinor)
assert ok : "Atabix gebruikt stylesheet-versie ${major}.${minor}, verwacht minimaal ${MIN_VERSION} - vraag de Atabix-formulierbeheerder de stylesheet in het scenario bij te werken"
log.info("Atabix-stylesheetversie OK: ${major}.${minor} (minimaal vereist: ${MIN_VERSION})")

