import com.eviware.soapui.support.XmlHolder

def requestXml = mockRequest.requestContent
def holder = new XmlHolder(requestXml)

holder.namespaces["zkn"] = "http://www.egem.nl/StUF/sector/zkn/0310" 
holder.namespaces["stuf"] = "http://www.egem.nl/StUF/StUF0301"

def actualReferentieNummerProxySentToMockService = holder.getNodeValue("//zkn:stuurgegevens/stuf:referentienummer") 

context.getMockService().getProject().setPropertyValue("GeefZaakDetailsReferentieNummerMockServiceReceived", actualReferentieNummerProxySentToMockService)

context.getMockService().getProject().setPropertyValue("GeefLijstZaakdocumentenReferentieNummerMockServiceReceived", actualReferentieNummerProxySentToMockService)

// Both GeefZaakDetails and geefLijstZaakdocumenten requests triggers this operation of BeantwoordVraag mock service. 
// It is probably because of both messages' wrapper named "zakLv01" and SoapUI cannot distinguish them and returns the first operation.
// First operation is geefZaakDetails under BeantwoordVraag MockService.
// We use this mock operation for our test purposes for both geefZaakDetails and geefLijstZaakdocumenten.
// This problem of SoapUI doesn't impact our test verification.

return "zakLa01"

import com.eviware.soapui.support.XmlHolder
def requestXml = mockRequest.requestContent def holder = new XmlHolder(requestXml)
holder.namespaces["zkn"] = "http://www.egem.nl/StUF/sector/zkn/0310" holder.namespaces["stuf"] = "http://www.egem.nl/StUF/StUF0301"
def actualReferentieNummerProxySentToMockService = holder.getNodeValue("//zkn:stuurgegevens/stuf:referentienummer")
context.getMockService().getProject().setPropertyValue("GeefZaakdocumentLezenReferentieNummerMockServiceReceived", actualReferentieNummerProxySentToMockService)
return "edcLa01"

con:soapui-project.con:beforeSaveScript:
def clearProperties(obj) {
    for (prop in obj.propertyList) {
        if (prop.getValue() && !prop.getValue().startsWith('$')){   // value doesn't contain property expansion
            prop.setValue("")
        }
    }
}

for (testSuite in project.getTestSuiteList()) {
    log.info("Clearing custom properties on TestSuite: ${testSuite.getName()}")
    clearProperties(testSuite)

    for (testCase in testSuite.getTestCaseList()) {
        def propertiesTestStep = testCase.getTestStepByName("Properties");
        	if(propertiesTestStep != null){
			clearProperties(propertiesTestStep)
			log.info("Clearing Properties teststep on: ${testSuite.getName()}:${testCase.getName()}")
        	}
    }
}
